steps.script:
var d = tree.root.get_node("Main").get_node("FightController").fight_resolution_dock
var txt = ""
for row in d.modifier_box.get_children():
	txt += row.text + "|"
print("[cus11e kaptaris] dock modifiers: ", txt)
return d.modifier_header.visible and txt.contains("Kaptaris")

var ph = PhaseManager.get_current_phase_instance()
var found := false
for d in ph.dice_log:
	if str(d.get("context", "")) == "hit_roll_melee":
		print("[cus11e kaptaris] hit_roll_melee ledger: ", d.get("modifier_ledger", []))
		for e in d.get("modifier_ledger", []):
			if str(e.get("source", "")).find("Kaptaris") >= 0:
				found = true
return found

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.get("_tab_dice_button") != null:
			panel = n
			break
if panel == null:
	return "panel not found"
panel._tab_dice_button.emit_signal("pressed")
return true
